'use client';

import { useEffect, useRef, useState } from 'react';
import type { Lang } from '@/config/site';
import { extra } from '@/i18n/extra';

/**
 * The narrated explainer video.
 *
 * - Nothing is downloaded until the visitor presses play (preload="none"); until then
 *   they see a poster frame with a play button.
 * - Phones get the vertical cut, wider screens the 16:9 one.
 * - Captions (WebVTT, generated by scripts/make-captions.mjs) are available from the
 *   player's own controls.
 * - `base` is empty on the site and the live origin in the single-file landing export,
 *   where the media cannot travel inside the HTML.
 */
export function VideoShowcase({ lang, base = '' }: { lang: Lang; base?: string }) {
  const t = extra(lang).video;
  const video = useRef<HTMLVideoElement>(null);
  const [started, setStarted] = useState(false);
  const [tall, setTall] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia('(max-width: 640px)');
    const sync = () => setTall(mq.matches);
    sync();
    mq.addEventListener('change', sync);
    return () => mq.removeEventListener('change', sync);
  }, []);

  // A different cut is a different file: start over with its poster.
  useEffect(() => setStarted(false), [tall]);

  const cut = tall ? 'tall' : 'wide';
  const file = `${base}/video/${lang}-${cut}`;

  const play = () => {
    setStarted(true);
    void video.current?.play().catch(() => setStarted(false));
  };

  return (
    <section className="video" id="video" aria-labelledby="video-title">
      <div className="wrap">
        <div className="video-head">
          <p className="eyebrow" data-reveal>{t.eyebrow}</p>
          <h2 className="h-section" id="video-title" data-reveal>{t.title}</h2>
          <p className="lead" data-reveal>{t.lead}</p>
        </div>

        <div className={`video-frame ${cut}`} data-video-frame>
          <video
            key={cut}
            ref={video}
            src={`${file}.mp4`}
            poster={`${file}.jpg`}
            preload="none"
            playsInline
            controls={started}
            crossOrigin={base ? 'anonymous' : undefined}
            aria-label={t.title}
            onEnded={() => setStarted(false)}
          >
            <track kind="captions" srcLang={lang} label={t.captions} src={`${file}.vtt`} />
          </video>
          {!started && (
            <button className="video-play" type="button" onClick={play}>
              <span className="video-play-icon" aria-hidden="true">
                <svg viewBox="0 0 24 24"><path d="M8.5 5.5v13l10.5-6.5z" fill="currentColor" /></svg>
              </span>
              <span className="video-play-label">{t.play} <span className="mono">{t.durations[cut]}</span></span>
            </button>
          )}
        </div>
      </div>
    </section>
  );
}
